import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) c = readByte();
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int k = scanner.nextInt();

        int[] t = new int[n];
        for (int i = 0; i < n; i++) {
            t[i] = scanner.nextInt();
        }

        Arrays.sort(t);
        // Inverte para ter ordem decrescente (1-indexed: tDec[1] >= tDec[2] >= ... >= tDec[n])
        int[] tDec = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            tDec[i] = t[n - i];
        }

        final long INF = (long) 4e18;
        long[] prev = new long[n + 1];
        long[] curr = new long[n + 1];

        // Para j = 0, custo é 0 para todo i >= 0
        Arrays.fill(prev, 0);

        for (int j = 1; j <= k; j++) {
            int minI = 3 * j;
            for (int i = 0; i < minI; i++) {
                curr[i] = INF;
            }
            for (int i = minI; i <= n; i++) {
                long diff = tDec[i - 1] - tDec[i];
                long cost = diff * diff;
                long take = prev[i - 2] + cost;
                long notTake = curr[i - 1];
                curr[i] = Math.min(notTake, take);
            }

            long[] temp = prev;
            prev = curr;
            curr = temp;
        }

        System.out.println(prev[n]);
    }
}
